package org.bedrockBytecode

import kotlin.test.Test
import kotlin.test.assertTrue
import org.bedrockBytecode.engine.hashStringVm


class LibraryTest {
    @Test fun someLibraryMethodReturnsTrue() {
        val classUnderTest = Library()
        assertTrue(classUnderTest.someLibraryMethod(), "someLibraryMethod should return 'true'")
    }
    @Test fun hashFxn() {
        val hashMaps  = mapOf("io.console.print" to 10634550992374585907uL,
                                "io.console.read_line" to 11174140223897499719uL,
                                "io.file.read" to 4100346326675936995uL,
                                "io.file.write" to 5796946121189188610uL,
                                "io.file.append" to 6067790551616150519uL,
                                "io.file.exists" to 3578709093477348543uL,
                                "io.file.length" to 13002782639914582063uL,
                                "u64.from_string" to 6853399315506211892uL,
                                "i64.from_string" to 16076306678625843816uL,
                                "f64.from_string" to 6978109133763550277uL,
                                "u64.to_string" to 8149430780573344407uL,
                                "i64.to_string" to 15461467554190651459uL,
                                "f64.to_string" to 417476877239542410uL,
                                "netty.http.fetch.get" to 11010129295708776231uL,
                                "netty.http.fetch.post" to 2177886027683028183uL,
                                "netty.http.fetch.delete" to 4578525684858902234uL,
                                "netty.http.fetch.patch" to 2643427006699934393uL,
                                "native.crypto" to 17462398302516461213uL,
                                "native.crypto.hash.sha1" to 1767425188059820176uL,
                                "native.crypto.hash.sha256" to 16178062944712262086uL,
                                "native.crypto.aes" to 13915692733155026236uL,
                                "native.crypto.aes.decrypt" to 15309485253778038099uL,
                                "native.crypto.aes.encrypt" to 6126835074412710047uL,
                                "native.crypto.rsa" to 7400704809625680629uL,
                                "native.crypto.rsa.keygen" to 2269231673879273138uL,
                                "native.crypto.rsa.encrypt" to 13098002821755477902uL,
                                "native.crypto.rsa.decrypt" to 13757309509234704246uL,
                                )

        for(key in hashMaps.keys){
            assertTrue(hashMaps.get(key) == hashStringVm(key),"hashing gave unexpected result for string "+key+", expected " + hashMaps.get(key) + ", found "+hashStringVm(key))
        }
    }
}
